      "碎盾者": "Schildbrecher",
      "大量前排战士；前排死亡时强化友军。": "Viele Krieger der vorderen Reihe; Verbündete werden stärker, wenn eine Einheit der vorderen Reihe stirbt.",
      "暗影猎手": "Schattenjaeger",
      "幽林之眼": "Auge des Dunklen Waldes",
      "后排远程与狙击单位可以越过前排。": "Einheiten der hinteren Reihe mit Fernkampf und Scharfschützen können über die vordere Reihe schlagen.",
      "翠影女王": "Smaragd-Schatten-Königin",
      "王庭的盗贼女王": "Diebkönigin des Königlichen Hofes",
      "统御整个哥布林王庭的盗贼女王，每个行动回合都会呼来两名普通哥布林。": "Die Diebkönigin, die den gesamten Goblin-Hof regiert; jeden Handlungszug ruft sie zwei gewöhnliche Goblins herein.",
      "无尽绿潮": "Endlose Grüne Welle",
      "每个敌方行动回合，在空位免费召唤2个普通哥布林。": "Jeden feindlichen Handlungszug beschwöre 2 gewöhnliche Goblins in leeren Feldern kostenlos.",
      "丰穗战母·布蕾娅": "Ernte-Kriegsmutter Breya",
      "金麦农场的熊族统领": "Bären-Häuptling des Goldenen Weizenfeldes",
      "守护熊族新家园的战母。每回合召唤丰穗近卫，每3回合强化场上全部熊族。": "Die Kriegsmutter, die das neue Zuhause der Bären bewacht. Beschwört jeden Zug einen Ernte-Wächter und stärkt alle Bären auf dem Feld alle 3 Züge.",
      "护田战令": "Feld-Wächter-Dekret",
      "每个敌方行动回合召唤1个5攻/7血的丰穗近卫。": "Jeden feindlichen Handlungszug einen 5/7 Ernte-Wächter beschwören.",
      "丰收之怒": "Zorn der Ernte",
      "每3个敌方行动回合，使场上所有熊族随从获得+1/+2。": "Alle 3 feindlichen Handlungszüge geben alle Bären-Diener auf dem Feld +1/+2.",
      "碧露大贤者·涅芙莉": "Große Weise Nephrie des Azurblauen Taus",
      "梦幻森林的史莱姆引路者": "Schleim-Leiterin des Traumwaldes",
      "拒绝离开故土的大贤者。每个行动回合恢复首领和全部史莱姆生命，每3回合分裂出两名碧露近卫。": "Eine große Weise, die ihre Heimat nicht verlassen will. Jeden Handlungszug heilt sie sich selbst und alle Schleim-Diener, alle 3 Züge spaltet sie zwei Azurblaue-Tau-Wächter ab.",
      "不灭胶质": "Unsterbliches Gel",
      "每个敌方行动回合，为首领恢复10点生命，并为所有史莱姆随从恢复5点生命。": "Jeden feindlichen Handlungszug stelle 10 Leben für den Boss und 5 Leben für alle Schleim-Diener wieder her.",
      "碧露分裂": "Azurblaue-Tau-Abteilung",
      "每3个敌方行动回合，免费召唤2个4攻/12血碧露近卫。": "Alle 3 feindlichen Handlungszüge beschwöre 2 4/12 Azurblaue-Tau-Wächter kostenlos.",
      "森林狼王": "Wald-Wolfkönig",
      "裂月之牙": "Fang des Zerrissenen Mondes",
      "每3回合召唤幼狼；每4回合发动狼王咆哮。": "Beschwört jeden 3. Zug einen Wolf-Welpen; entfesselt alle 4 Züge das Heulen des Wolfkönigs.",
      "狼王号令": "Befehl des Wolfkönigs",
      "每3个敌方回合，在空位免费召唤1只幼狼。": "Jeden 3. feindlichen Zug einen 1 Wolfs-Welpe in einem leeren Feld kostenlos beschwöre.",
      "裂月咆哮": "Heulen des Zerrissenen Mondes",
      "每4个敌方回合，使所有狼类随从永久获得+1攻击。": "Alle 4 feindlichen Züge erhalten alle Wolf-Diener dauerhaft +1 Angriff.",
      "银灰狼女猎手": "Silbergrauer Wolf-Jägerin",
      "千枝城的灰牙首领": "Graufang-Anführer der Stadt der Tausend Zweige",
      "避开翡翠城追兵、占据千枝城废墟的狼族首领。每回合都会呼唤一只迅猛的灰狼投入战斗。": "Der Wolfhäuptling, der den Verfolgern der Smaragdstadt entging und die Ruinen der Stadt der Tausend Zweige eroberte. Jeden Zug ruft sie einen schnellen grauen Wolf in die Schlacht.",
      "灰狼增援": "Grauer Wolf-Verstärkung",
      "每个敌方行动回合，召唤1只4攻/1血、可立即攻击随从的突击灰狼。": "Jeden feindlichen Handlungszug einen 4/1 Sturm-Grauer Wolf beschwöre, der sofort Diener angreifen kann.",
      "千枝城魔族军官团": "Dämonische Offiziere der Stadt der Tausend Zweige",
      "拒绝退避的重建者": "Wiederaufbauer, die sich weigern, sich zurückzuziehen",
      "第五关剧情结束后驻扎于千枝城的魔族据点。随从均为20攻/200血，属于长期挑战内容。": "Die Dämonenfestung, die sich nach Kapitel 5 in der Stadt der Tausend Zweige stationiert hat. Alle Diener sind 20/200 — Langzeit-Herausforderungsinhalte.",
