      "赤穗熊骑": "Rote-Garben-Bären-Reiter",
      "麦田稻草魔像": "Weizenfeld-Stroh-Golem",
      "留守的农民夫妇": "Das Bauernpaar, das blieb",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "Ganz ruhig jetzt. Diese Bären haben hier niemanden getötet. Als sie zum Hof kamen, trieben sie nur die Dorfbewohner zur königlichen Hauptstadt.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "Wir blieben, weil wir von ihnen nie Feindseligkeit gespürt haben. Anfangs wussten sie nicht einmal, wie man einen Pflug hält—sie zerwühlten die Felder nur durch rohe Kraft.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "Später lehrten wir die Bärenmänner, die Kanäle zu reparieren und Weizen zu säen, und lehrten die Bärenfrauen, die Bienenstöcke zu pflegen und die Ernte einzubringen. Sie lernen langsam, aber sie verschwenden niemals Nahrung.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "Sie sparen den wärmsten Platz in der Scheune für ihre Jungen und bringen den ersten Sack neuen Weizens zu unserer Tür. Zumindest in unseren Augen sind sie nicht so böse wie die Gerüchte sagen.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "Wenn du weitergehen musst, sieh es mit deinen eigenen Augen, bevor du urteilst. Was hier geschah, könnte nicht nur ein einfacher Fall von Monstern sein, die ein Dorf erobern.",
