      "余烬尚温，帐篷里似乎遗留着补给。": "Die Glut ist noch warm; Vorräte scheinen in den Zelten hinterlassen worden zu sein.",
      "仔细搜索": "Durchsuche sorgfältig",
      "50%获得30金币，否则受到5点伤害": "50%: Gewinne 30 Gold; ansonsten erhalte 5 Schaden",
      "立刻离开": "Verlasse sofort",
