      "流浪剑士": "Wandernder Schwertkämpfer",
      "一位满身伤痕的剑士愿意传授战场经验。": "Ein vernarbter Schwertkämpfer bietet an, seine Kampferfahrung zu teilen.",
      "支付30金币": "Zahle 30 Gold",
