      "魔晶已经失去稳定的法力回路，只余适合研习的微弱辉光。": "Der Kristall hat seinen stabilen Mana-Kreislauf verloren; nur ein schwaches Leuchten zum Studieren bleibt.",
      "研究辉光": "Studiere das Leuchten",
      "失去5生命，随机一张法术牌获得2点经验": "Verliere 5 Leben; eine zufällige Zauber-Karte erhält 2 EP",
      "保持警惕": "Bleibe wachsam",
