      "合法军籍、家属安置与面向兽族的城市教育": "Legale Einstellung, Familien-Umsiedlung und Stadtbildung für Bestienfolk",
      "不灭凰族": "Unsterbliche Phönixe",
      "火灾救援、灾后重建与对重生者的身份登记": "Feuerrettung, Katastrophenwiederaufbau und Identitätsregistration für die Wiedergeborenen",
      "黑锋骑士团": "Schwarzkanten-Orden",
      "让锋刃只指向准备好应战的人": "Lass die Klinge nur auf diejenigen zeigen, die bereit sind zu kämpfen",
      "蒲公英花灵": "Löwenzahn-Fae",
      "市集、印刷术与允许异族登台的演出许可": "Märkte, Druckerei und Aufführungslizenzen, die anderen Rassen die Bühne lassen",
      "血斧角斗场": "Blutbeil-Arena",
      "裁判最好离远点，我的胜利通常会溅到前三排": "Der Schiedsrichter sollte zurücktreten – meine Siege benetzen normalerweise die ersten drei Reihen",
      "晶辉学院": "Kristallglanz-Akademie",
      "用晶体测量魔力，让法术可以被复现": "Messung der Magie mit Kristallen, damit Zauber reproduziert werden können",
      "鹿角兽人": "Geweihe Bestienfolk",
      "护林法、共享牧道与边地自治议会": "Waldschutzgesetze, gemeinsame Hüterouten und Selbstverwaltungsräte an der Grenze",
      "机巧侏儒": "Uhrwerk-Gnome",
      "专利制度、公开船坞与事故追责": "Patentsysteme, offene Werften und Verantwortung für Unfälle",
      "虚空观测站": "Leere-Observatorium",
      "用长期观测区分天启、幻觉和噪声": "Langfristbeobachtung zur Unterscheidung von Offenbarung, Illusion und Rauschen",
      "黄金狮鹫族": "Goldene Greifen",
      "空骑军籍、兽族居住权与救援航线": "Luftfahrer-Einstellung, Bestienfolk-Wohnrecht und Rettungsflugstrecken",
      "我加入王国不是为了变成人类，而是因为这里允许我保留自己，也允许我凭本事向前。": "Ich bin dem Königreich nicht beigetreten, um menschlich zu werden, sondern weil ich hier ich selbst bleiben kann und aufgrund meiner eigenen Verdienste vorankommen kann.",
      "血统只决定出生，制度和选择才决定我们能否并肩站在这里。": "Nur die Blutlinie bestimmt, wo wir geboren werden; Institutionen und Entscheidungen bestimmen, ob wir hier Seite an Seite stehen können.",
      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "Heute repräsentiere ich nicht Unterwerfung, sondern ein Königreich, wo andere Rassen offen konkurrieren und fairen Applaus gewinnen können.",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "Schön. Mich so weit zu treiben beweist, dass die Hauptstadt einen respektablen Gegner wirklich willkommen heißt.",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "Ich werde jene Vorurteile nicht bestätigen, dass andere Rassen in der Wildnis verborgen gehören. Komm – letzte Runde!",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "Du gewinnst. Möge diese Arena weiter beweisen: Menschen und andere Rassen können konkurrieren, ohne sich gegenseitig zu hassen.",
      "出牌再快一点。观众买票不是来看你思考人生的。": "Spiel schneller. Das Publikum hat nicht für Karten gekauft, um zuzusehen, wie du über das Leben nachdenkst.",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "Du nennst das eine Kampflinie? Meine Wäscheleine ist schwärer zu durchbrechen.",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "Entspann dich, ich lasse dir etwas Würde – ich warte wenigstens auf den Schiedsrichter-Ruf, bevor ich lache.",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "Höre auf, auf die Scoreboard zu schauen. Sie wechselt die Seite nicht, nur weil du lange genug starrt.",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "Dieser letzte Zug war anständig. Aber um mich zum Schweigen zu bringen, hast du noch eine Strecke vor dir.",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "Winke der Menge noch nicht zu! Ich spare meine Rückkehr für, wenn es am lautesten ist.",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "Du gewinnst heute. Nächstes Mal schlage ich dich zuerst, dann reiche ich eine Beschwerde über diesen Boden ein, der dich offensichtlich bevorzugt.",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "Kümmere dich nicht um mich, ich zeichne deine Spielgewohnheiten auf. Die wirklich gefährlichen Daten kommen oft von selbstbewussten Menschen.",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "Jeder Handelsschlag schränkt die Antwort ein. Ein paar Züge noch und dir bleibt nur eine Wahl.",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "Die Arena ist ehrlicher als das Labor: falsche Theorien verlieren sofort Leben.",
      "放心，若你击败我，我会如实把结论写进报告。": "Sei versichert, wenn du mich schlägst, schreibe ich die Schlussfolgerung getreulich in meinen Bericht.",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "Die Daten weichen von der Vorhersage ab. Gut – Forschung ohne Überraschungen ist die langweiligste Art.",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "Die Stichprobe überprüft nun den Forscher... Ich muss zugeben, dieses Ergebnis ist sehr überzeugend.",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "Schlussfolgerung bestätigt: dein augenblickliches Urteil schlägt mein Modell. Die nächste Fassung meines Papiers wird das sagen.",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "Es gibt keine wahren Feinde in der Arena, nur Leute, die bereit sind, ihre Fähigkeiten im Sonnenlicht zu zeigen.",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "Verlasse die Linie nicht, um dein Leben zu retten. Ehre kommt vom Eingehen von Risiken, nicht davon, sie zu vermeiden.",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "Das Publikum erinnert sich an das Ergebnis; ein Krieger sollte sich an die unter Druck getroffenen Entscheidungen erinnern.",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "Halte nicht zurück. Die beste Art, einen Gegner zu respektieren, ist, die Kraft zu bringen, die wirklich gewinnen will.",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "Ein schöner Frontalangriff. Der Schmerz vergeht; dein Urteil zu verlieren ist die echte Niederlage.",
      "只剩最后一点生命，正好用来检验最后一点意志。": "Gerade noch ein Leben – perfekt zum Testen des letzten Funkens Willensstärke.",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "Das Spiel ist entschieden. Ich habe deine Taktiken auswendig gelernt und meine Applaus für diejenigen aufbewahrt, die es verdienen.",
      "并": "und",
      "，它们可以立即攻击": ", und sie können sofort angreifen",
      "和": "und",
