      "生命": "Leben",
      "战场上没有狼类随从，技能未强化任何单位。": "Es gibt keine Wolf-Diener auf dem Schlachtfeld; die Fähigkeit hat keine Einheiten verstärkt.",
      "🐺 狼王咆哮发动！": "🐺 Wolfs-König Heulen entfesselt!",
      "接管战场，准备主动反击": "Übernehme das Schlachtfeld und bereite dich auf einen Gegenangriff vor",
      "封锁全部前排": "Versiegle die ganze vordere Reihe",
      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "Die vier Sukkubus-Offiziere weigern sich zurückzuziehen und greifen sofort mit 20 Angriff an; der Trupp wird zurückgedrängt, aber Kapitel 5 zählt immer noch als besiegt.",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "Die vier Sukkubus-Offiziere greifen nicht an; sie halten nur die Barriere aufrecht und kaufen zwei Züge für die Flucht ihres Kameraden.",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "Stadt der Tausend Zweige Gegenangriff beginnt: die vier Sukkubus-Offiziere greifen den Trupp einzeln mit 20 Angriff an.",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "Der Angriff der vier Offiziere durchbricht die Linie, und die Vorhut der Dämonenallianz überquert den Riss, um die Ruinen zu erobern; der Trupp wird aus Stadt der Tausend Zweige vertrieben.",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "Die vier Sukkubus-Offiziere zerstreuten den Trupp, aber die Silber-Graue Wolf-Jägerin wurde bereits besiegt: Kapitel 5s Geschichte ist abgeschlossen, und alle Beute und Belohnungen werden wie gewohnt vergeben.",
      "你的英雄倒下了。冒险结束。": "Dein Held ist gefallen. Das Abenteuer ist vorbei.",
