      "选择发光的敌方目标；若有突破路线，也可以点击敌方英雄。": "Wähle ein leuchtend gegnerisches Ziel; wenn eine Bahn durchbrochen ist, kannst du auch den gegnerischen Held anklicken.",
      "武器已举起：选择敌方随从；若有突破路线，也可以攻击敌方英雄。": "Waffe erhoben: wähle einen gegnerischen Diener; wenn eine Bahn durchbrochen ist, kannst du auch den gegnerischen Held angreifen.",
