      "进军哥布林王庭": "Marschiere auf den Goblin-Hof",
      "踏入密林": "Betrete die Tiefenwälder",
      "踏入千枝城废墟": "Betrete die Ruinen der Tausend Zweige",
      "追寻银灰狼女猎手": "Verfolge die silbergraue Wolf-Jägerin",
      "追寻碧露大贤者": "Suche den Großen Weisen des Azurblauen Taus",
      "踏入金麦农场": "Betrete den Goldenen-Weizen-Hof",
      "会见丰穗战母": "Triff die Erntekriegsmutter",
      "进军王庭": "Marschiere zum Hof",
      "挑战翠影女王": "Fordere die Smaragdschatten-Königin heraus",
      "击穿战线": "Durchbreche die Schlachtlinie",
      "直面狼王": "Stelle dich dem Wolf-König",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "Kapitel 5 liegt in den alten Ruinen südlich der Smaragdstadt. Grauenwölfe und andere Bestien expandieren schnell ihr Territorium mit Überfällen; am Ende stellst du dich der silbergrauen Wolf-Jägerin.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "Kapitel 4 hat zwanzig Schleim-Boss-Knoten. Sie haben dickes Leben, niedrigen Angriff und regenerieren sich ständig; folge dem leuchtenden Bach tief in den Wald, um dich dem Großen Weisen Nephrie des Azurblauen Taus zu stellen.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "Kapitel 3 hat zwanzig Bären-Boss-Knoten und ein Bauernhaus. Folge den Farmtrassen, um das besetzte Dorf zu untersuchen, und stelle dich schließlich Erntekriegsmutter Breya.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "Kapitel 2 hat zwanzig Boss-Knoten. Schiebe entlang der Goblin-Armee-Verteidigungen voran und stelle dich schließlich der Smaragdschatten-Königin mit 200 Leben.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "Stelle dein Heer über vier Kampfbahnen mit vorderer und hinterer Reihe auf, reiße eine Lücke auf und überquere dreizehn Nebeldwald-Knoten. Jeder Sieg wird Stärke für die nächste Expedition.",
      "重新开始本关": "Starten Sie dieses Kapitel neu",
      "当前没有伤员": "Keine verletzten Einheiten",
      "单机卡牌闯关冒险": "Ein Einzelspieler-Kartenabenteuer",
      "关卡选择": "Kapitelauswahl",
      "英雄档案": "Held-Profil",
      "卡组编辑": "Deck-Ersteller",
      "设置": "Einstellungen",
      "队伍营地": "Team-Lager",
      "每项卡牌训练或救治服务均需30金币。阵亡的真实随从会进入伤员名单，救治后才能重新出战。": "Jedes Kartentrain- oder Heilungsservice kostet 30 Gold. Echte Diener, die sterben, gehen auf die Verletztenliste und müssen geheilt werden, bevor sie wieder kämpfen können.",
      "⚔️ 随从训练 · 30金币": "⚔️ Diener-Training · 30 Gold",
      "选择任意一张未满级随从牌，增加2点经验": "Wähle eine beliebige Dienerkarte unter maximaler Stufe, um 2 EP zu erhalten",
      "✨ 法术训练 · 30金币": "✨ Zauber-Training · 30 Gold",
      "选择任意一张未满级法术牌，增加2点经验": "Wähle eine beliebige Zauberkarte unter maximaler Stufe, um 2 EP zu erhalten",
      "🗡️ 武器训练 · 30金币": "🗡️ Waffen-Training · 30 Gold",
      "选择任意一张未满级武器牌，增加2点经验": "Wähle eine beliebige Waffenkarte unter maximaler Stufe, um 2 EP zu erhalten",
      "🩹 救治伤员 · 30金币": "🩹 Heile die Verletzten · 30 Gold",
      "前后排战线": "Vordere und hintere Reihe",
      "每列前排保护后排。前后排都清空后，该路线变为突破口。": "Jede vordere Reihe einer Bahn schützt ihre hintere Reihe. Sobald beide geklärt sind, wird diese Bahn durchbrochen.",
