      "点击同一张卡即可连续训练。面板不会关闭，每次增加2点经验并立即更新等级和进度。": "Klicke auf dieselbe Karte, um sie wiederholt zu trainieren. Das Fenster bleibt offen; jeder Klick addiert 2 EP und aktualisiert sofort Stufe und Fortschritt.",
