      "战斗经验、法力和技能成长会跨冒险保存。": "Kampf-EP, Mana und Fertigkeit-Wachstum werden zwischen Abenteuern weitergegeben.",
      "曾任王都护卫队长。野兽接连觉醒后，他认为只守住一座王都远远不够，于是离开王都、集结自己的小队，奔赴各地平定乱局。": "Einst Hauptmann der Königsgarde in der Hauptstadt. Als die Tiere eines nach dem anderen erwachten, erkannte er, dass es bei Weitem nicht genügt, nur die Hauptstadt zu schützen. Er verließ sie, sammelte seinen eigenen Trupp und zog aus, um überall im Land die Unruhen niederzuschlagen.",
      "生命上限": "Maximales Leben",
      "统领试炼": "Prüfungen des Befehlshabers",
