      "冒险通关": "Abgeschlossene Abenteuer",
      "技能最高3级。每赢得一场竞技场比赛，当前装备技能获得2点经验；夺冠还会获得决赛对手的英雄技能。": "Fertigkeiten gehen bis Stufe 3. Jeder gewonnene Arenakampf gibt deiner ausgerüsteten Fertigkeit 2 EP; der Turniersieg gewährt auch die Held-Fertigkeit des Finalisten.",
