      "英雄等级、经验、法力、金币、收藏、卡组和当前冒险均保存在此浏览器的 localStorage 中。": "Held-Stufe, EP, Mana, Gold, Sammlung, Deck und aktuelles Abenteuer werden in diesem Browser-LocalStorage gespeichert.",
