      "选择最终 Boss 的头像进入对应关卡。依次通关会开放新的地区与英雄等级上限。": "Wähle das Porträt eines Endgegners, um dieses Kapitel zu betreten. Wenn du Kapitel in Reihenfolge abschließt, werden neue Regionen freigeschaltet und die Held-Stufen-Obergrenze erhöht.",
