      "返回主界面": "Zur Hauptseite zurück",
      "需要：含有女王血液的河水": "Erforderlich: Flusswasser, das das Blut der Königin enthält",
      "可挑战 · 首次通关最大法力 +1": "Verfügbar · erstes Freischalten: Maximales Mana +1",
      "先完成上一关": "Schließe die vorherige Prüfung zuerst ab",
      "再次挑战": "Erneut herausgefordert",
      "开始试炼": "Prüfung starten",
      "第七关“女王的低语”已经可以进入": "Prüfung 7, \"Das Flüstern der Königin\", ist jetzt offen",
      "击败第一关第一个Boss，取得女王血河水后，才能进入最终试炼。": "Besiege den ersten Boss von Kapitel 1 und erhalte das Blut der Königin Flusswasser, um die letzte Prüfung zu betreten.",
      "海港城市 · 老兵训练场": "Hafenstadt · Trainingsgelände der Veteranen",
      "归乡之战幸存者的七堂课": "Sieben Lektionen von Überlebenden des Kriegs der Heimkehr",
      "每关首次通关永久增加1点最大法力；没有碎片，也没有总上限。重复挑战不会重复获得法力。": "Das Freischalten von jeder Prüfung addiert dauerhaft 1 Maximales Mana; keine Scherben und keine Gesamtobergrenze. Wiederholte Freischaltungen gewähren kein Mana wieder.",
      "返回世界地图": "Zur Weltkarte zurück",
      "这项试炼尚未解锁。": "Diese Prüfung ist noch nicht freigeschaltet.",
      "你再次完成了这项试炼；首次通关奖励已经领取。": "Du hast diese Prüfung erneut abgeschlossen; die Belohnung für das erste Freischalten wurde bereits beansprucht.",
      "统领试炼完成": "Prüfung des Befehlshabers abgeschlossen",
      "返回训练场": "Zurück zum Trainingsgelände",
      "试炼暂未通过": "Prüfung noch nicht bestanden",
      "试炼不会消耗远征生命或地图进度。调整战术后可以立即重试。": "Prüfungen verbrauchen nicht die Expeditions-Gesundheit oder den Kartenschritt. Passe deine Taktiken an und versuche es sofort erneut.",
      "请先击败森林狼王解锁第二关。": "Besiege zuerst den Wolf-König des Waldes, um Kapitel 2 freizuschalten.",
      "请先击败翠影女王解锁第三关。": "Besiege zuerst die Smaragdschatten-Königin, um Kapitel 3 freizuschalten.",
      "请先击败丰穗战母解锁第四关。": "Besiege zuerst die Erntekriegsmutter, um Kapitel 4 freizuschalten.",
      "请先击败碧露大贤者解锁第五关。": "Besiege zuerst den Großen Weisen des Azurblauen Taus, um Kapitel 5 freizuschalten.",
      "等待晋级": "Wartet auf Qualifizierer",
      "未知选手": "Unbekannter Wettkämpfer",
      "实时淘汰赛程": "Live-Knockout-Plan",
      "王冠杯对阵图": "Kronenpokal-Klammer",
