      "淘汰": "Eliminiert",
      "王都中央": "Herz der Hauptstadt",
      "荣耀竞技场": "Arena des Ruhms",
      "64名英雄使用相同卡池展开六轮淘汰赛，对手卡牌等级每场随机。": "64 Helden teilen denselben Kartenfonds in einem sechsrundigen Knockout; die Kartenstufen der Gegner sind bei jedem Kampf zufällig.",
      "王冠杯 · 64强": "Kronenpokal · Top 64",
      "晋级奖金：32强100金币、16强200、8强400、4强800、亚军1200、冠军1600。": "Fortschrittspreise: Top 32 100 Gold, Top 16 200, Top 8 400, Top 4 800, Zweiter 1200, Champion 1600.",
      "报名参赛": "Registrieren",
      "王冠杯冠军": "Kronenpokal-Champion",
      "参加新一届": "Ein neues Turnier betreten",
      "本届比赛止步": "Bei diesem Turnier eliminiert",
      "重新报名": "Erneut registrieren",
      "使用玩家当前卡组，每张卡随机1–5级": "Verwendet dein aktuelles Deck, jede Karte auf zufälliger Stufe 1–5",
      "开始比赛": "Kampf starten",
      "64人单败淘汰赛": "64-Spieler-Einzelausscheidung",
      "2点英雄技能经验": "2 Held-Fertigkeit-EP",
      "（已拥有）": "(bereits besessen)",
      "已加入英雄技能收藏，可在英雄档案装备。": "Zu deiner Held-Fertigkeitssammlung hinzugefügt; rüste sie im Held-Profil aus.",
      "，你成为本届王冠杯冠军！": ", du bist der Champion des diesjährigen Kronenpokals!",
      "。下一名对手已经就位。": ". Dein nächster Gegner ist bereit.",
      "竞技场胜利": "Arena-Sieg",
      "竞技场战报": "Arena-Bericht",
      "遗憾落败": "Knappe Niederlage",
      "本届赛事已经结束，已获得的晋级奖金全部保留。": "Dieses Turnier ist vorbei; alle Fortschrittspreise, die du verdient hast, bleiben bei dir.",
      "查看赛果": "Ergebnisse anzeigen",
      "魔族重建据点": "Von Dämonen wieder aufgebaute Hochburg",
      "· 尚未挑战": "· noch nicht herausgefordert",
      "与留守的农民夫妇交谈": "Sprich mit dem Bauernpaar, das geblieben ist",
      "先抵达相邻农田节点": "Erreiche zuerst den benachbarten Bauernhof-Knoten",
      "农民夫妇": "Bauernpaar",
      "千枝城废墟二十野兽首领路线图": "Routenkarte von zwanzig Bestienraffern in den Tausendzweig-Ruinen",
      "梦幻森林二十史莱姆首领路线图": "Routenkarte von zwanzig Schleim-Raffern im Traumwald",
      "金麦农场二十首领路线图": "Routenkarte von zwanzig Raffern auf dem Goldweizen-Hof",
      "哥布林王庭二十节点路线图": "Routenkarte von dreizehn Knoten vor Gericht der Kobolde",
      "迷雾森林十三节点路线图": "Routenkarte von dreizehn Knoten im Nebelwald",
      "千枝城古城废墟": "Tausendzweig-Ruinen",
      "梦幻森林": "Traumwald",
      "金麦农场": "Goldweizen-Hof",
      "哥布林王庭": "Kobold-Gericht",
      "迷雾森林远征": "Nebelwald-Expedition",
      "灰狼和其他野兽速度极快，许多单位登场即可攻击。击败全部节点后，魔族联军会在废墟建立据点，之后可以反复挑战强大的军官与魔族军队。": "Grauwölfe und andere Bestien sind äußerst schnell und viele Einheiten können direkt nach ihrem Eintreffen angreifen. Nach deinem Sieg an jedem Knoten bauen die Dämonen-Allianz eine Festung in den Ruinen auf, wo du gegen mächtige Offiziere und dämonische Truppen kämpfen kannst.",
      "沿发光溪流与林间小径推进。每个史莱姆首领都会治疗自身与随从；击败节点后开启所有相邻路线，首胜卡牌会在战后揭晓。": "Folge dem leuchtenden Strom und den Waldpfaden. Jeder Schleim-Raffer heilt sich selbst und ihre Untergebenen; das Besiegen eines Knotens öffnet alle benachbarten Routen, und Karten für den ersten Sieg werden nach dem Kampf enthüllt.",
      "沿金色路线推进。击败节点后会开启所有相邻路线；抵达农舍旁的节点后，可与留守的农民夫妇交谈。每个首领的首胜奖励会在战后揭晓。": "Folge der goldenen Route. Das Besiegen eines Knotens öffnet alle benachbarten Routen; sobald du den Knoten neben dem Bauernhof erreichst, kannst du mit dem Bauernpaar sprechen, das dort geblieben ist. Die Erste-Sieg-Belohnung jedes Bosses wird nach dem Kampf enthüllt.",
      "击败任一节点即可开启相邻路线；翠影女王会在抵达右上方终点后开放。大部分节点由哥布林军团驻守。": "Das Besiegen jedes Knotens öffnet die benachbarten Routen; die Smaragdschatten-Königin wird verfügbar, sobald du den letzten Knoten oben rechts erreichst. Die meisten Knoten werden von der Koboldarmee gehalten.",
      "金边节点由更强的敌人驻守；首次击败会获得未知战利品。击败节点后仍可回到岔路挑战相邻路线。": "Knoten mit goldenem Rand werden von stärkeren Gegnern gehalten; die erste Niederlage gewährt unbekannte Beute. Nach dem Besiegen eines Knotens kannst du trotzdem zur Gabelung zurückgehen, um benachbarte Routen zu erledigen.",
      "击败一个节点后，所有相邻的未完成节点都会解锁。战败不会清空本关进度，切换关卡也会分别保存。": "Nachdem du einen Knoten besiegst, werden alle benachbarten unvollendeten Knoten freigeschaltet. Eine Schlacht zu verlieren löscht diese Kapitel nicht, und jedes Kapitel wird separat gespeichert, wenn du wechselst.",
      "⭐ 本轮": "⭐ Dieser Durchgang",
      "⚔️ 已完成": "⚔️ Abgeschlossen",
      "🛡️ 失败": "🛡️ Fehlgeschlagen",
      "退出当前关卡": "Kapitel verlassen",
      "先抵达农舍旁的农田节点。": "Erreiche zuerst den Landwirtschafts-Knoten neben dem Bauernhof.",
      "金麦农场 · 留守者的证言": "Goldweizen-Hof · Zeugnis derer, die blieben",
      "他们并不要求你放下武器，只希望你在见到丰穗战母之前，先知道这些熊族并未伤害原来的村民。": "Sie bitten dich nicht, deine Waffen zu senken—nur, dass du vor dem Treffen mit der Erntekriegs-Mutter weißt, dass diese Bären die ursprünglichen Dorfbewohner nie verletzt haben.",
      "我会亲眼判断": "Ich urteile mit meinen eigenen Augen",
      "请先完成第五关结局，解锁千枝城魔族重建据点。": "Beende zuerst das Ending von Kapitel 5, um die dämonische Festung in der Stadt der Tausend Zweige freizuschalten.",
      "极限挑战": "Ultimative Herausforderung",
      "千枝城驻军暂时退却": "Tausendzweig-Garnison zieht sich zurück",
      "你击退了不可一世的魔族驻军，获得500金币。她们仍会继续重建千枝城，之后仍可再次挑战。": "Du hast die arrogante dämonische Garnison abgewehrt und 500 Gold verdient. Sie werden die Stadt der Tausend Zweige immer wieder aufbauen und du kannst sie später erneut herausfordern.",
      "返回废墟地图": "Zurück zur Rutenkarte",
      "魔族军官守住了据点": "Die Dämonischen Offiziere hielten die Festung",
      "20攻/200血的驻军压倒了小队。这场失败不会重置第五关进度，也不会造成额外惩罚。": "Die 20/200 Garnison überwältigte den Trupp. Diese Niederlage setzt nicht den Fortschritt von Kapitel 5 zurück und verursacht keine zusätzlichen Strafen.",
      "每一列的前排会保护其身后的后排。": "Die vordere Reihe jeder Bahn schützt die hintere Reihe dahinter.",
      "击败前排后，才能普通攻击该列后排。": "Erst nach dem Besiegen der vorderen Reihe kannst du normalerweise die hintere Reihe dieser Bahn angreifen.",
      "前后排全部为空时，该路线被突破。": "Wenn beide Reihen leer sind, ist diese Bahn durchbrochen.",
      "通过突破路线可以直接攻击敌方英雄。": "Du kannst den gegnerischen Helden direkt durch eine durchbrochene Bahn angreifen.",
      "你的最大法力不会每回合增加。": "Deine maximale Mana steigt nicht pro Zug.",
      "海港的统领试炼是永久提高最大法力的唯一途径。": "Die Hafens-Befehlshaber-Prüfungen sind die einzige Möglichkeit, die maximale Mana dauerhaft zu erhöhen.",
      "首次战斗": "Erster Kampf",
      "六条战场要诀": "Sechs wesentliche Kampfprinzipien",
      "开始战斗": "Kampf starten",
