      "千枝城反击战结束": "Tausendzweig-Gegenoffensive vorbei",
      "首杀固定奖励": "Garantierte Erste-Töten-Belohnung",
      "关键物品": "Schlüsselelement",
      "河水中的猩红丝线与古老月辉产生共鸣。它能开启统领试炼第七关。": "Scharlachrote Fäden im Flusswasser resonieren mit uraltem Mondlicht. Es öffnet Befehlshaber-Prüfung 7.",
      "已收入行囊，可用于统领试炼第七关。": "In deinem Rucksack gelagert; wird für Befehlshaber-Prüfung 7 verwendet.",
      "战斗胜利": "Sieg",
      "选择一项额外奖励": "Wähle eine Bonus-Belohnung",
      "千枝城的旗帜重新升起": "Das Banner der Tausend Zweige erhebt sich erneut",
      "梦幻森林归于寂静": "Der Traumwald verstummt",
      "金麦农场的战事落幕": "Die Kämpfe auf dem Goldweizen-Hof enden",
      "哥布林王庭陷落": "Das Kobold-Gericht fällt",
      "密林重见曙光": "Morgenröte kehrt in die Tiefenwälder zurück",
      "你击败银灰狼女猎手后，五位魅魔军官没有继续退避。她们救下狼族首领，以20点攻击的力量击溃小队，并决定在千枝城废墟建立魔族据点、重建这座千年前的共居之城。第五关奖励照常结算，英雄等级上限提升至25级；废墟地图上已经开放可反复挑战的魔族驻军。": "Nachdem du die Silber-Grau-Wolf-Jägerin besiegt hast, stellen die fünf Sukkubus-Offiziere das Retreat ein. Sie retten den Wolfschamanen, besiegen den Trupp mit 20 Angriff und entscheiden, eine dämonische Festung in den Tausendzweig-Ruinen zu bauen, um diese Stadt wieder aufzubauen, wo die Völker vor tausend Jahren zusammenlebten. Kapitel-5-Belohnungen werden wie üblich gewährt und die Held-Stufe-Obergrenze steigt auf 25; eine dämonische Garnison, die du wiederholt herausfordern kannst, ist jetzt auf der Rutenkarte offen.",
      "你击败了碧露大贤者·涅芙莉，迫使史莱姆族群退回森林深处，并将英雄等级上限提升至20级。": "Du hast den Großweisen Nephrie des Azurbaus besiegt, die Schleim in die Tiefen des Waldes zurückgetrieben und die Held-Stufe-Obergrenze auf 20 erhöht.",
      "你击败了丰穗战母·布蕾娅，完成第三关并解锁东部梦幻森林与英雄20级上限。": "Du hast die Erntekriegs-Mutter Breya besiegt, Kapitel 3 abgeschlossen und den östlichen Traumwald sowie eine Held-Stufe-Obergrenze von 20 freigeschaltet.",
      "你击败了翠影女王，完成第二关的二十场首领战，并解锁王城南部的金麦农场与英雄15级上限。": "Du hast die Smaragdschatten-Königin besiegt, Kapitel 2s zwanzig Boss-Kämpfe abgeschlossen und den südlich der Hauptstadt gelegenen Goldweizen-Hof sowie eine Held-Stufe-Obergrenze von 15 freigeschaltet.",
      "你击败了森林狼王，并解锁第二关与英雄10级上限。最大法力只在统领试炼中提升。": "Du hast den Waldwolf-König besiegt, Kapitel 2 freigeschaltet und eine Held-Stufe-Obergrenze von 10 erreicht. Die maximale Mana steigt nur durch die Befehlshaber-Prüfungen.",
