      "将第五关设置为前19个首领已经击败，只留下银灰狼女猎手。英雄、金币、收藏、卡组以及其他关卡存档均不会改变。": "Stellt Kapitel 5 so ein, dass die ersten 19 Bosse besiegt sind und nur die Silber-Grau-Wolf-Jägerin bleibt. Dein Held, Gold, Sammlung, Deck und andere Kapitel-Speicherungen ändern sich nicht.",
