      "两回合已过，四位魅魔军官一同跃入裂隙，带着{0}撤离战场。": "Zwei Züge sind vergangen; die vier Sukkubus-Offiziere springen zusammen in den Riss und ziehen sich mit {0} zurück.",
      "{0}个再生随从在回合开始时共恢复{1}点生命。": "{0} Regenerations-Diener stellen insgesamt {1} Leben zu Beginn des Zuges wieder her.",
      "我方第{0}回合开始：法力恢复为{1}/{2}，场上{3}个随从，手牌{4}张。": "Dein Zug {0} beginnt: Mana wiederhergestellt auf {1}/{2}, {3} Diener auf dem Spielfeld, {4} Karten auf der Hand.",
      "{0}被击败！": "{0} ist besiegt!",
      "原始费用 {0}": "Originalkosten {0}",
      "{0}费": "{0} Mana",
      "选择一个敌方前排随从施放{0}。": "Wähle einen feindlichen Diener in der vorderen Reihe um {0} auf zu wirken.",
      "{0}回合": "{0} Züge",
      "第{0}回合": "Zug {0}",
      "{0}已被第五名军官救走。四名20攻/200血军官拒绝撤离，正在直接杀退小队。": "{0} wurde vom fünften Offizier gerettet. Die vier 20/200 Offiziere weigern sich zu ziehen und treiben den Trupp direkt zurück.",
      "{0}已被第五名军官带走。四名10攻/200血军官封锁前排，并将在{1}回合后撤离。": "{0} wurde vom fünften Offizier fortgetragen. Die vier 10/200 Offiziere versiegeln die vordere Reihe und werden sich in {1} Zügen zurückziehen.",
      "你的回合 · 第{0}回合": "Dein Zug · Zug {0}",
      "{0}的回合": "{0}s Zug",
      "法力每回合恢复至 {0}/{1}，不会自动增长。": "Mana wird zu {0}/{1} jeden Zug wiederhergestellt und wächst nicht automatisch.",
      "{0} {1} · {2}费": "{0} {1} · {2} Mana",
