      "{0}第{1}关 · 已完成{2}节点": "{0} Kapitel {1} · {2} Knoten geleert",
      "救治全部{0}名伤员": "Heile alle {0} Verletzten",
      "· 英雄生命 {0}/{1}，同时恢复满生命": "· Heldenleben {0}/{1}, auch vollständig wiederhergestellt",
      "每回合恢复至 {0}/{1}。永久上限不封顶，只能由统领试炼首次通关提升。": "Wird zu {0}/{1} jeden Zug wiederhergestellt. Die permanente Obergrenze hat keine Grenze und kann nur durch Erstgänge von Prüfungen des Befehlshabers erhöht werden.",
      "{0} 场胜利 · {1} 次通关 · 收藏 {2} 张": "{0} Siege · {1} Gänge · {2} Karten gesammelt",
