      "裂角蛮王": "Bruchhorn-Kriegsherr",
      "银叶游侠": "Silberblatt-Waldläufer",
      "银盾骑士": "Silberschild-Ritter",
      "森灵德鲁伊": "Hain-Druidin",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "Die jüngste Meisterschützin der Waldgrenze; ihre Pfeile dringen durch dichtes Geäst und finden Feinde hinter den Linien.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "Eine Hexe, die den Magierturm verließ, um allein den Riss zu erforschen; sie zerteilt Mana in unzählige kaum ausweichbare Geschosse.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "Eine Heilige, vom Sonnentempel an die Front gesandt, die glaubt, dass jeder Soldat es verdient, noch einmal aufzustehen.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "Ein Kriegsherr der Nordstämme, der mit seinem eigenen Blut die Wut seiner Krieger entfacht.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "Anführer der Mondwald-Waldläufer, der Feinde stets Bogenschützen in den Schatten erblicken lässt, wo keine sein dürften.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "Ein Veteran des Morgenlicht-Ordens der Hauptstadt; sein Schildwall ist nie einen Schritt zurückgewichen.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "Eine Druidin, geboren aus dem Herzen des Urhains; jeder Setzling, den sie pflanzt, wächst zu einem uralten Baum heran, der den Wald beschützt.",
      "穿林箭": "Durchdringender Pfeil",
      "奥术飞弹": "Arkane Geschosse",
      "晨曦复苏": "Morgenrot-Erneuerung",
      "血怒狂击": "Blutraserei",
      "林间伏兵": "Waldhinterhalt",
      "圣盾壁垒": "Aegiswall",
      "萌芽古树": "Sprießender Uralter",
      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "Ignoriert den Schutz der vorderen Reihe und fügt einem beliebigen feindlichen Diener {0} Schaden zu; stirbt er, ziehe 1 Karte.",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "Feuert {0} arkane Geschosse ab, die je 1 Schaden an einem zufälligen feindlichen Diener oder dem feindlichen Helden verursachen.",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "Stellt alle befreundeten Diener vollständig wieder her und stellt {0} Leben deines Helden wieder her.",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "Dein Held verliert 2 Leben; ein befreundeter Diener erhält in diesem Zug +{0} Angriff und kann sofort erneut angreifen.",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "Beschwört in der hinteren Reihe einen Fernkampf-Schattenblatt-Bogenschützen mit {0}/{1}; er kann sofort Diener angreifen.",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "Alle befreundeten Diener der vorderen Reihe erhalten dauerhaft +{0} Leben; ist deine vordere Reihe leer, beschwöre einen Aegis-Wächter mit 0/{1}.",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "Beschwört einen Uralten Setzling mit {0}/{1}; zu Beginn jedes deiner Züge erhält er dauerhaft +1/+1.",
