      "晨曦照亮战线：随从共恢复{0}点生命，英雄恢复{1}点生命。": "Das Morgenrot erhellt die Front: Diener stellen insgesamt {0} Leben wieder her, dein Held {1} Leben.",
      "{0}陷入血怒，本回合攻击力提升至{1}，可以立即攻击。": "{0} verfällt in Blutraserei: Angriff steigt in diesem Zug auf {1}, er kann sofort angreifen.",
