      "新英雄「{0}」将从头开始远征。之后的进度会自动保存到所选栏位。": "Der neue Held „{0}“ beginnt die Expedition von vorn. Der Fortschritt wird danach automatisch im gewählten Platz gespeichert.",
      "读取后，之后的进度会自动保存到该栏位。": "Nach dem Laden wird der Fortschritt automatisch in diesem Platz gespeichert.",
      "当前进度会自动保存到当前栏位；“保存到此”会把当前进度另存到所选栏位，并以它作为之后的自动保存栏位。": "Der Fortschritt wird automatisch im aktuellen Platz gespeichert; „Hier speichern“ kopiert ihn in den gewählten Platz und macht diesen zum neuen Autosave-Platz.",
